// A database where everyone can access the photos from the wedding and upload their own
// They will have to verify by using the email used when registering for the wedding!


// Info required to verify access (then give them session access because they wont want to login multiple times)
// Name
// Email
// Pin code from email!


import React, { useState } from 'react';

// Replace this template with the real verification request.
async function verifyAccess({ fullName }) {
    await new Promise((resolve) => setTimeout(resolve, 1200));
    return { verified: Boolean(fullName) };
}

export default function EventPhotos() {
    const [fullName, setFullName] = useState('');
    const [isVerifying, setIsVerifying] = useState(false);

    async function handleVerify(event) {
        event.preventDefault();
        if (isVerifying) return;

        setIsVerifying(true);
        try {
            await verifyAccess({ fullName });
        } finally {
            setIsVerifying(false);
        }
    }

    return (
        <div style={styles.page}>
            <style>{`@keyframes verifySpin { to { transform: rotate(360deg); } }`}</style>
            <h1 style={styles.heading}>Event Photos</h1>
            <p style={styles.description}>
                Welcome to the <b>Event Photos page</b>! </p>
            <p style={styles.description}>
                Here, you can access and upload photos from the wedding. To ensure privacy and security, please verify your access by providing your <b>full name</b>. Once verified, you'll have session access to view and share memories from this special event!
            </p>
            <center>
                <form style={styles.form}>
                    <input
                        type="text"
                        placeholder="Full Name"
                        style={styles.input}
                        value={fullName}
                        onChange={(event) => setFullName(event.target.value)}
                        disabled={isVerifying}
                    /> <i style={styles.caution}>*This name will be tagged on all uploaded photos</i><p></p>
                    
                    <button type="submit" style={styles.button} onClick={handleVerify} disabled={isVerifying}>
                        {isVerifying ? <span style={styles.spinner} aria-label="Verifying" /> : 'Verify'}
                    </button>
                </form>
            </center>

            <div style={styles.share}>
                <i>To access the event photos, Please scan this QR code</i> <p></p>
                <img src="https://api.qrserver.com/v1/create-qr-code/?size=150x150&data=https://photos.weddingofjamesandkatie.com" alt="QR Code" />
            </div>

        </div>

    );

}


const styles = {
    page: {
        background: "#faf9f7",
        minHeight: "100vh",
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        justifyContent: "center",
        fontFamily: "Georgia, 'Times New Roman', serif",
        padding: "2rem",
    },
    heading: {
        fontSize: "clamp(28px, 6vw, 48px)",
        fontWeight: 300,
        color: "#2C2C2A",
        margin: "0 0 1rem",
        lineHeight: 1.2,
    },
    description: {
        fontSize: 16,
        color: "#5F5E5A",
        maxWidth: 600,
        textAlign: "center",
    },
    form: {
        display: "flex",
        flexDirection: "column",
        alignItems: "center",
        marginTop: "2rem",
    },
    input: {
        padding: "0.5rem",
        fontSize: 16,
        border: "1px solid #ccc",
        borderRadius: 4,
        marginBottom: "1rem",
        width: "100%",
        maxWidth: 300,
    },
    button: {
        padding: "0.5rem 1rem",
        fontSize: 16,
        backgroundColor: "#2C2C2A",
        color: "#fff",
        border: "none",
        borderRadius: 4,
        cursor: "pointer",
    },
    caution: {
        fontSize: 12,
        marginTop: "-0.5rem",

    },

    share: {
        // all the way at the bottom of the page
        position: "absolute",
        top: "85%",
        fontSize: 14,
        color: "#5F5E5A",
        textAlign: "center",    
    }

}
